-- Logbook – Supabase Schema (full snapshot, regenerated from the live DB)
-- This is the authoritative current state and the bootstrap source for
-- supabase/migrations/20260528000000_legacy_schema_baseline.sql. It was
-- generated by introspecting the production database (pg_get_functiondef,
-- pg_policies, pg_constraint, information_schema) so policy and function bodies
-- are verbatim. Keep it in sync on schema changes (see CLAUDE.md → "Datenbank").

-- Migration 0132: on a fresh project, `public`'s default privileges (as
-- provisioned by Supabase) grant `anon` direct EXECUTE on every function
-- created afterward, REGARDLESS of a later `REVOKE EXECUTE ... FROM PUBLIC`
-- on that function — that revoke only removes PUBLIC-inherited access, not
-- an explicit direct grant from a default-privileges rule. Discovered when
-- two brand-new SECURITY DEFINER functions (Migration 0131) stayed callable
-- by anon despite the usual REVOKE FROM PUBLIC + GRANT TO authenticated
-- pattern (see the "Grant-Falle" note further down, which only covers the
-- PUBLIC-inheritance path). Closing it here, before any function in this
-- script is created, so a from-scratch rebuild doesn't reintroduce it for
-- every function defined below.
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public
  REVOKE EXECUTE ON FUNCTIONS FROM anon;

-- Supabase production grants authenticated users table/sequence access by
-- default and relies on RLS for row-level authorization. Make that project
-- default explicit in this snapshot so a from-scratch Preview created by the
-- postgres migration role has the same ACL baseline as production.
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public
  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO authenticated;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public
  GRANT USAGE, SELECT, UPDATE ON SEQUENCES TO authenticated;

-- ── Tables ────────────────────────────────────────────────────────────────────

-- App-external device event tables.  They predate the recorded migration
-- history, are retained for the separate ingestion app, and intentionally have
-- RLS without client policies.
CREATE TABLE public.motion_events (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sensor_id integer NOT NULL,
  sensor_name text NOT NULL,
  room text NOT NULL,
  presence boolean NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.door_events (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  door_name text NOT NULL,
  state text NOT NULL CHECK (state IN ('open', 'closed')),
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.motion_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.door_events ENABLE ROW LEVEL SECURITY;

-- The ingestion app listens to these two external tables through Realtime.
-- Keep clean snapshots aligned with production without failing when the
-- publication or either table is not present in a minimal local database.
DO $publication$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    IF NOT EXISTS (
      SELECT 1 FROM pg_publication_tables
      WHERE pubname = 'supabase_realtime'
        AND schemaname = 'public'
        AND tablename = 'motion_events'
    ) THEN
      ALTER PUBLICATION supabase_realtime ADD TABLE public.motion_events;
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM pg_publication_tables
      WHERE pubname = 'supabase_realtime'
        AND schemaname = 'public'
        AND tablename = 'door_events'
    ) THEN
      ALTER PUBLICATION supabase_realtime ADD TABLE public.door_events;
    END IF;
  END IF;
END
$publication$;

-- tier (Migration 0240): account tier, server-authored. Granted by
-- grant_lifetime_if_qualified() when an account clears the founding-member bar
-- (5 completed workouts AND 150 logged minutes) while seats remain. A client
-- write to tier/tier_granted_at is reverted by zane_profiles_protect_tier,
-- because the "own profile" policy is FOR ALL and would otherwise let anyone
-- award themselves lifetime access.
-- Signup approval (approved column, Migration 0074/0076) was removed in
-- Migration 0241: registration is open and no longer gated.
CREATE TABLE public.zane_profiles (
  id   uuid NOT NULL,
  name text NOT NULL,
  tier text NOT NULL DEFAULT 'free',
  tier_granted_at timestamptz,
  x_handle text,
  x_handle_public boolean NOT NULL DEFAULT true,
  x_handle_prompt_opted_out boolean NOT NULL DEFAULT false,
  CONSTRAINT zane_profiles_tier_check CHECK (tier IN ('free', 'lifetime', 'premium'))
);

COMMENT ON COLUMN public.zane_profiles.x_handle IS
  'Optional canonical X handle, stored as @name; accepted input is normalized client-side.';
COMMENT ON COLUMN public.zane_profiles.x_handle_public IS
  'Whether future public/social features may display the user X handle; admins can still see it.';
COMMENT ON COLUMN public.zane_profiles.x_handle_prompt_opted_out IS
  'Whether the one-time optional X-handle prompt has been handled; true means it will not automatically appear again.';

-- Global app config (single row).
-- force_update_nonce (Migration 0131): set by admin_force_update() to push
-- the "New version available" banner to every client without an sw.js bump.
-- lifetime_seats_total (Migration 0240): size of the founding-member cohort,
-- in config rather than in the trigger so it can be raised without a deploy.
CREATE TABLE public.zane_app_config (
  id int PRIMARY KEY DEFAULT 1,
  force_update_nonce text,
  social_mode text NOT NULL DEFAULT 'normal',
  social_transport text NOT NULL DEFAULT 'broadcast',
  coaching_transport text NOT NULL DEFAULT 'broadcast',
  lifetime_seats_total int NOT NULL DEFAULT 75,
  CONSTRAINT zane_app_config_social_mode_check CHECK (social_mode IN ('normal', 'maintenance')),
  CONSTRAINT zane_app_config_social_transport_check CHECK (social_transport IN ('legacy', 'broadcast')),
  CONSTRAINT zane_app_config_coaching_transport_check CHECK (coaching_transport IN ('legacy', 'broadcast')),
  CONSTRAINT zane_app_config_singleton CHECK (id = 1)
);

-- Feature map ADMIN override layer. Master content lives in the versioned
-- src/feature-map-db.js catalog; this table holds only the admin's hide / edit /
-- add / reorder overrides keyed by catalog card id, previewed in the admin
-- screen and baked into the catalog at publish time. Admin-only (read + write).
-- Migration 0154 created it as a content table; 0155 reshaped it to overrides.
CREATE TABLE public.zane_feature_map (
  card_id text PRIMARY KEY,
  hidden boolean NOT NULL DEFAULT false,
  is_custom boolean NOT NULL DEFAULT false,
  cat text,
  name text,
  role text CHECK (role IS NULL OR role IN ('user','coach','both')),
  summary text,
  actions jsonb,
  sort int,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- Feature map PUBLISHED mirror. The layer everyone (public page + all logged-in
-- users) actually renders on top of the code catalog. publish_feature_map()
-- promotes the draft (zane_feature_map) here; discard_feature_map() resets the
-- draft back to it. Admin-only direct read (for the unpublished-changes diff);
-- everyone else reads via get_public_feature_map(). Migration 0156.
CREATE TABLE public.zane_feature_map_published (
  card_id text PRIMARY KEY,
  hidden boolean NOT NULL DEFAULT false,
  is_custom boolean NOT NULL DEFAULT false,
  cat text,
  name text,
  role text CHECK (role IS NULL OR role IN ('user','coach','both')),
  summary text,
  actions jsonb,
  sort int,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.zane_exercises (
  id text NOT NULL,
  user_id uuid NOT NULL,
  name text NOT NULL,
  tags text[] DEFAULT '{}'::text[],
  note text NOT NULL DEFAULT ''::text,
  category text,
  unilateral boolean NOT NULL DEFAULT false,
  equipment text,
  progression_reps integer,
  movement_type text,
  no_weight_reps boolean NOT NULL DEFAULT false,
  log_mode text,
  pull_bodyweight boolean NOT NULL DEFAULT false,
  -- Migration 0243. Three-way successor to pull_bodyweight for bodyweight
  -- exercises: null = type the weight, 'pull' = pre-fill the last logged
  -- bodyweight, 'plus_load' = type only the added load (weighted pull-ups,
  -- belted dips). pull_bodyweight is still written in lockstep so a client on
  -- an older cached build keeps pre-filling.
  bodyweight_mode text CHECK (bodyweight_mode IS NULL OR bodyweight_mode IN ('pull', 'plus_load')),
  youtube_url text,
  note_pinned boolean NOT NULL DEFAULT false,
  progression_increment numeric CHECK (progression_increment IS NULL OR progression_increment > 0),
  -- Migration 0254. Ordered horn names for a multi-horn plate-loaded machine,
  -- e.g. ["Standard","Mid","High"]. Non-empty = log a weight per horn. No
  -- second mode column on purpose (see no_weight_reps vs log_mode).
  horn_labels jsonb
);

CREATE TABLE public.zane_schedules (
  id text NOT NULL,
  user_id uuid NOT NULL,
  name text NOT NULL,
  days jsonb NOT NULL DEFAULT '[]'::jsonb,
  archived boolean NOT NULL DEFAULT false,
  versions jsonb NOT NULL DEFAULT '[]'::jsonb,
  is_flex boolean NOT NULL DEFAULT false,
  sessions_per_week integer,
  mesocycle_weeks integer,
  mesocycle_start_rir integer,
  mesocycle_end_rir integer,
  mesocycle_rir_enabled boolean NOT NULL DEFAULT true,
  mesocycle_autoregulate boolean NOT NULL DEFAULT false,
  mesocycle_autoregulate_mode text,
  program_type text,
  program_data jsonb,
  is_template boolean NOT NULL DEFAULT false
);

CREATE TABLE public.zane_sessions (
  id text NOT NULL,
  user_id uuid NOT NULL,
  schedule_id text,
  day_id text,
  day_name text,
  date timestamp with time zone,
  ended timestamp with time zone,
  entries jsonb NOT NULL DEFAULT '[]'::jsonb,
  started_at timestamp with time zone,
  duration_minutes integer,
  feel text,
  is_bonus boolean NOT NULL DEFAULT false,
  is_freestyle boolean NOT NULL DEFAULT false,
  is_deload boolean NOT NULL DEFAULT false,
  is_cleanup boolean NOT NULL DEFAULT false,  -- 0251: cleanup week, see docs/database.md
  meso_recap jsonb,
  readiness text,
  signal_weight text,
  cycle_pos integer,
  -- Server clock at first completion (Migration 0242). Written only by
  -- zane_sessions_stamp_completion, immutable afterwards, never accepted from
  -- the client: it is the only session timestamp a client cannot forge, and the
  -- founding-member day-spread check depends on that.
  completed_server_at timestamptz,
  imported boolean NOT NULL DEFAULT false -- historical import; never counts as a live completion
);

CREATE TABLE public.zane_session_entries (
  id text NOT NULL,
  session_id text NOT NULL,
  user_id uuid NOT NULL,
  entry_idx integer NOT NULL,
  ex_id text,
  name text NOT NULL DEFAULT ''::text,
  planned_sets integer,
  planned_reps integer,
  note text NOT NULL DEFAULT ''::text,
  superset_group text,
  planned_reps_per_set integer[],
  planned_reps_max integer,
  planned_progression_offset integer,
  planned_techniques text[]
);

CREATE TABLE public.zane_sets (
  id text NOT NULL,
  session_id text NOT NULL,
  entry_id text NOT NULL,
  user_id uuid NOT NULL,
  set_idx integer NOT NULL,
  kg numeric,
  reps integer,
  reps_l integer,
  reps_r integer,
  time_sec integer,
  done boolean NOT NULL DEFAULT false,
  skipped boolean NOT NULL DEFAULT false,
  warmup boolean NOT NULL DEFAULT false,
  technique text,
  drops jsonb,
  -- Migration 0243. Load added on top of bodyweight for a plus_load exercise.
  -- kg still holds the TOTAL, so e1RM/PR/volume/autoregulation are unchanged;
  -- this is only what the user typed. Implied bodyweight = kg - added_kg, which
  -- freezes it at logging time.
  added_kg numeric,
  -- Migration 0254. Per-horn breakdown for a multi-horn machine,
  -- [{"label":"Mid","kg":20}, ...]. Self-describing rather than positional so
  -- reordering an exercise's horns cannot re-label sets already in history.
  -- kg holds the plain SUM; no leverage math, the ratios are unpublished.
  horn_loads jsonb,
  updated_at timestamp with time zone NOT NULL DEFAULT now()
);

CREATE TABLE public.zane_cardio_logs (
  id               text        NOT NULL,
  user_id          uuid        NOT NULL,
  date             text        NOT NULL,
  type             text,
  duration_minutes integer     NOT NULL,
  distance_m       numeric,
  pace_feeling     integer     CHECK (pace_feeling BETWEEN 1 AND 6),
  effort           integer     CHECK (effort BETWEEN 1 AND 10),
  note             text,
  created_at       timestamp with time zone NOT NULL DEFAULT now(),
  session_id       text        -- links a logged cardio session back to its zane_sessions row
);

CREATE TABLE public.zane_daily_logs (
  id           text        NOT NULL,
  user_id      uuid        NOT NULL,
  date         text        NOT NULL,
  weight       numeric,
  waist_cm     numeric,
  hips_cm      numeric,
  chest_cm     numeric,
  arm_cm       numeric,
  thigh_cm     numeric,
  calf_cm      numeric,
  body_fat_pct numeric,
  steps        integer,
  calories     integer,
  protein      integer,
  carbs        integer,
  fat          integer,
  fiber        integer,
  water_ml     integer,
  note         text,
  adherence          numeric,
  targets_snap       jsonb,
  off_plan_note      text,
  meal_of_choice     boolean     DEFAULT false,
  meal_of_choice_hour smallint,
  food_day_closed    boolean              DEFAULT false,
  daily_coach_fields jsonb,
  ai_summary              text,
  ai_summary_generated_at timestamp with time zone,
  updated_at         timestamp with time zone NOT NULL DEFAULT now(),
  created_at         timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT zane_daily_logs_user_id_date_key UNIQUE (user_id, date)
);

-- Adaptive TDEE history (migration 0260): one reproducible estimate per
-- calculation endpoint. The source logs remain the calculation source; this
-- row preserves whether the user applied or skipped the result and the target
-- snapshot that was accepted at that point.
CREATE TABLE public.zane_adaptive_tdee_history (
  id                  text NOT NULL,
  user_id             uuid NOT NULL,
  as_of_date          date NOT NULL,
  window_start        date NOT NULL,
  window_end          date NOT NULL,
  tdee_kcal           integer NOT NULL,
  avg_calories_kcal   integer NOT NULL,
  weight_start_kg     numeric NOT NULL,
  weight_end_kg       numeric NOT NULL,
  weight_change_kg    numeric NOT NULL,
  weight_rate_kg_week numeric NOT NULL,
  day_span            integer NOT NULL,
  calorie_days        integer NOT NULL,
  weigh_ins           integer NOT NULL,
  decision            text NOT NULL DEFAULT 'reconstructed'::text,
  source              text NOT NULL DEFAULT 'reconstructed'::text,
  targets_snapshot    jsonb,
  calculated_at       timestamp with time zone NOT NULL DEFAULT now(),
  decided_at          timestamp with time zone,
  created_at          timestamp with time zone NOT NULL DEFAULT now(),
  updated_at          timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT zane_adaptive_tdee_history_pkey PRIMARY KEY (id),
  CONSTRAINT zane_adaptive_tdee_history_user_id_as_of_date_key UNIQUE (user_id, as_of_date),
  CONSTRAINT zane_adaptive_tdee_history_day_span_check CHECK ((day_span > 0)),
  CONSTRAINT zane_adaptive_tdee_history_calorie_days_check CHECK ((calorie_days > 0)),
  CONSTRAINT zane_adaptive_tdee_history_weigh_ins_check CHECK ((weigh_ins > 1)),
  CONSTRAINT zane_adaptive_tdee_history_decision_check CHECK ((decision = ANY (ARRAY['applied'::text, 'kept'::text, 'skipped'::text, 'reconstructed'::text]))),
  CONSTRAINT zane_adaptive_tdee_history_source_check CHECK ((source = ANY (ARRAY['live'::text, 'reconstructed'::text])))
);

REVOKE ALL ON public.zane_adaptive_tdee_history FROM PUBLIC, anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.zane_adaptive_tdee_history TO authenticated;

CREATE TABLE public.zane_skips (
  id text NOT NULL,
  user_id uuid,
  date text NOT NULL,
  day_id text,
  day_name text,
  skip_reason text,
  skipped_at timestamp with time zone DEFAULT now()
);

CREATE TABLE public.zane_user_settings (
  user_id uuid NOT NULL,
  active_schedule_id text,
  active_meal_template_id text,   -- Migration 0199: active meal plan pointer (mirrors active_schedule_id)
  cycle_index integer NOT NULL DEFAULT 0,
  last_advanced_date date,
  unit text,
  rest_default integer NOT NULL DEFAULT 120,
  in_progress_session_id text,
  cycle_start_date text,
  push_enabled boolean DEFAULT false,
  rest_big integer DEFAULT 180,
  rest_medium integer DEFAULT 120,
  rest_small integer DEFAULT 90,
  auto_open_rest_timer boolean NOT NULL DEFAULT false,
  cycle_week_view boolean DEFAULT false,
  -- Reporting-only boundary for weekly summaries, Friends metrics and coach check-ins.
  -- 0 = Monday ... 6 = Sunday; training-plan weekdays are unaffected.
  week_start_day smallint NOT NULL DEFAULT 0 CHECK (week_start_day BETWEEN 0 AND 6),
  accent_color text DEFAULT 'gold'::text,
  dark_mode text DEFAULT 'dark'::text,
  pushover_user_key text,
  use_pushover boolean DEFAULT false,
  week_plan_start_date date,
  tempo_enabled boolean DEFAULT false,
  tempo_eccentric numeric DEFAULT 4,
  tempo_concentric numeric DEFAULT 1,
  smart_progression boolean DEFAULT false,
  progression_range_top integer DEFAULT 4,
  equipment_config jsonb,
  custom_day_types text[] NOT NULL DEFAULT '{}'::text[],
  reminder_enabled boolean NOT NULL DEFAULT false,
  reminder_time text NOT NULL DEFAULT '07:00'::text,
  next_reminder_at timestamp with time zone,
  show_warmup_in_summary boolean NOT NULL DEFAULT true,
  show_regression boolean NOT NULL DEFAULT true,
  show_coaching_tab boolean DEFAULT false,
  be_your_own_coach boolean NOT NULL DEFAULT false,
  session_timeout_minutes integer DEFAULT 90,
  auto_close_notify jsonb,
  macro_targets jsonb,
  macro_calc jsonb,                          -- 0205: last inputs of the target estimator (prefill only; shape in docs/database.md)
  meal_windows jsonb,                        -- 0206: six ascending start hours for the food tracker meal categories, null = defaults
  meal_categories jsonb,                     -- 0261: custom [{id,label,startHour}] Food Tracker categories, null = built-in/legacy meal_windows
  show_health_tab boolean NOT NULL DEFAULT false,
  show_water_tab boolean NOT NULL DEFAULT false,   -- 0222: independent of show_health_tab, see docs/database.md
  show_food_tab boolean NOT NULL DEFAULT false,    -- 0222
  show_friends_tab boolean NOT NULL DEFAULT false, -- 0264: opt-in Friends preview tab
  social_push_messages boolean NOT NULL DEFAULT true, -- 20260815090739: direct/group message push
  social_push_friend_requests boolean NOT NULL DEFAULT true, -- 20260815090739
  social_push_finished_comments boolean NOT NULL DEFAULT false, -- 20260815090739
  social_push_friend_started boolean NOT NULL DEFAULT false, -- 20260815090739
  weight_fill_down boolean NOT NULL DEFAULT true,
  manual_calories boolean NOT NULL DEFAULT false,
  onboarding_completed boolean DEFAULT false,
  net_carbs boolean NOT NULL DEFAULT false,
  plan_mode boolean NOT NULL DEFAULT true, -- 0253: default flipped from false, existing rows backfilled to true
  hide_food_categories boolean NOT NULL DEFAULT false, -- 0214: flat hour timeline instead of meal-category header cards, display-only
  default_checkin_schema jsonb,
  status_mode text,
  status_mode_since timestamp with time zone,
  active_cardio_plan_id text,
  glucose_unit text DEFAULT 'mmol'::text,
  vip_background text,
  deload_prompt_dismissed_at timestamp with time zone,
  sw_version text,
  pin_all_notes boolean NOT NULL DEFAULT false,
  temp_unit text,
  hidden_health_cards jsonb,
  fever_threshold_c numeric DEFAULT 38,
  watermark_opacity integer,
  water_goal_ml integer DEFAULT 2000,
  water_start_time text DEFAULT '08:00'::text,
  water_end_time text DEFAULT '22:00'::text,
  water_bottles_today integer DEFAULT 0,
  water_bottles_date text,
  water_drinks jsonb,
  water_bottle_enabled boolean NOT NULL DEFAULT true,
  water_bottle_ml integer DEFAULT 1500,
  water_coffee_sizes jsonb,
  water_reminder_enabled boolean NOT NULL DEFAULT false,
  water_last_push_at timestamp with time zone,
  tz_offset_minutes integer,
  time_zone text,
  meal_reminder_enabled boolean NOT NULL DEFAULT false,
  meds_enabled boolean NOT NULL DEFAULT false,
  medication_reminder_enabled boolean NOT NULL DEFAULT false,
  daily_log_reminder_enabled boolean NOT NULL DEFAULT false,
  daily_log_reminder_time text NOT NULL DEFAULT '19:00'::text,
  daily_log_reminder_last_date text,
  pillbox_slots jsonb,
  fasting_protocol text,  -- 0249: intermittent fasting protocol preset ('16:8'|'18:6'|'20:4'|'omad'), null = off
  cleanup_percent integer NOT NULL DEFAULT 20,  -- 0251: cleanup week load reduction in percent (UI clamps 10-30)
  food_force_grams boolean NOT NULL DEFAULT false  -- 0252: opt-out, keep the food tracker in grams even when unit='lbs'
