ALTER TABLE public.zane_sessions ADD CONSTRAINT zane_sessions_feel_check CHECK ((feel = ANY (ARRAY['easy'::text, 'good'::text, 'hard'::text, 'very_hard'::text, 'max'::text])));

ALTER TABLE public.zane_session_entries ADD CONSTRAINT zane_session_entries_pkey PRIMARY KEY (id);
ALTER TABLE public.zane_session_entries ADD CONSTRAINT zane_session_entries_session_id_entry_idx_key UNIQUE (session_id, entry_idx);
ALTER TABLE public.zane_session_entries ADD CONSTRAINT zane_session_entries_session_id_fkey FOREIGN KEY (session_id) REFERENCES zane_sessions(id) ON DELETE CASCADE;
ALTER TABLE public.zane_session_entries ADD CONSTRAINT zane_session_entries_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;

