  USING (EXISTS ( SELECT 1 FROM zane_coaching zc
    WHERE zc.client_id = zane_body_temp_logs.user_id
      AND zc.coach_id = (select auth.uid()) AND zc.coach_id <> zc.client_id AND zc.status = 'active' AND zc.id NOT LIKE 'support_%'));

-- ── Water logs (migration 0180) ─────────────────────────────────────────────────
-- Multiple entries per day; amount always in ml. category is null for plain water,
-- 'other' for named drinks, 'custom' for free entries. The day's summed amount_ml
-- is written back into zane_daily_logs.water_ml by the client. Written directly.

CREATE TABLE zane_water_logs (
  id         text        PRIMARY KEY,
  user_id    uuid        NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  date       text        NOT NULL,                 -- YYYY-MM-DD
  time       text        NOT NULL,                 -- HH:MM local
  amount_ml  integer     NOT NULL,
  name       text,
  category   text,                                 -- null = plain water | 'other' | 'custom' | 'summary'
  breakdown  jsonb,                                -- collapsed-day drink breakdown, only set on category = 'summary'
  created_at timestamptz DEFAULT now()
);

CREATE INDEX zane_water_logs_user_date ON public.zane_water_logs USING btree (user_id, date DESC, "time" DESC);

ALTER TABLE zane_water_logs ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users manage own water logs"
  ON zane_water_logs FOR ALL TO public
  USING (((select auth.uid()) = user_id)) WITH CHECK (((select auth.uid()) = user_id));
CREATE POLICY "coaches read client water logs"
  ON zane_water_logs FOR SELECT TO public
  USING (EXISTS ( SELECT 1 FROM zane_coaching zc
    WHERE zc.client_id = zane_water_logs.user_id
      AND zc.coach_id = (select auth.uid()) AND zc.coach_id <> zc.client_id AND zc.status = 'active' AND zc.id NOT LIKE 'support_%'));

-- Nightly (hourly-checked) per-user collapse of past-day water_logs rows into
-- one summary row; see migration 0183 for the full rationale. Scheduled via
-- pg_cron ('water-log-collapse', not tracked in this snapshot like other cron
-- jobs), internal-only (no grant to authenticated).
CREATE OR REPLACE FUNCTION public.collapse_water_logs()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  r RECORD;
  v_total integer;
  v_milk integer;
  v_drinks jsonb;
  v_id text;
BEGIN
  FOR r IN
    SELECT wl.user_id, wl.date
    FROM zane_water_logs wl
    LEFT JOIN zane_user_settings us ON us.user_id = wl.user_id
    WHERE wl.date < to_char(
      (now() AT TIME ZONE 'UTC') + make_interval(mins => COALESCE(us.tz_offset_minutes, 0)),
      'YYYY-MM-DD'
    )
    GROUP BY wl.user_id, wl.date
    HAVING count(*) > 1
  LOOP
    SELECT
      sum(amount_ml)::int,
      sum(CASE WHEN category = 'other' THEN
        COALESCE((regexp_match(name, '\+\s*(\d+)ml Milk', 'i'))[1]::int, 0)
      ELSE 0 END)::int
    INTO v_total, v_milk
    FROM zane_water_logs
    WHERE user_id = r.user_id AND date = r.date;

    SELECT COALESCE(jsonb_object_agg(base_name, cnt), '{}'::jsonb) INTO v_drinks
    FROM (
      SELECT
        COALESCE(NULLIF(trim(regexp_replace(name, '\s*\+\s*\d+ml Milk', '', 'i')), ''), 'Other') AS base_name,
        count(*)::int AS cnt
      FROM zane_water_logs
      WHERE user_id = r.user_id AND date = r.date AND category = 'other'
      GROUP BY base_name
    ) t;

    v_id := gen_random_uuid()::text;

    DELETE FROM zane_water_logs WHERE user_id = r.user_id AND date = r.date;

    INSERT INTO zane_water_logs (id, user_id, date, "time", amount_ml, name, category, breakdown)
    VALUES (v_id, r.user_id, r.date, '00:00', v_total, NULL, 'summary',
      jsonb_build_object('drinks', v_drinks, 'milk', v_milk));
  END LOOP;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.collapse_water_logs() FROM PUBLIC;
-- Migration 0213: REVOKE FROM PUBLIC alone did NOT take it away from
-- authenticated (an ALTER DEFAULT PRIVILEGES rule grants EXECUTE on every new
-- function directly to that role, see the bump_api_usage note in 0208).
REVOKE EXECUTE ON FUNCTION public.collapse_water_logs() FROM authenticated;
REVOKE EXECUTE ON FUNCTION public.collapse_water_logs() FROM anon;

-- ── Food tracker (migration 0186) ───────────────────────────────────────────────
-- zane_foods: shared/global reference cache (Open Food Facts + USDA FoodData
-- Central), NOT per-user data. Populated only when a user selects a search
-- result to log (search-foods Edge Function, service-role key), keyed
-- deterministically (source:source_id) so re-selecting upserts instead of
-- duplicating.
-- zane_food_logs: per-user log entries, denormalized at write time so a later
-- refresh of a cached food never retroactively changes a historical entry.

CREATE TABLE zane_foods (
  id                text        PRIMARY KEY,          -- `${source}:${source_id}`
  source            text        NOT NULL CHECK (source IN ('off','usda')),
  source_id         text        NOT NULL,
  name              text        NOT NULL,
  brand             text,
  kcal_per_100g     numeric,
  protein_per_100g  numeric,
  carbs_per_100g    numeric,
  fat_per_100g      numeric,
  fiber_per_100g    numeric,
  sugar_per_100g     numeric,                             -- 0204
  sat_fat_per_100g   numeric,                             -- 0204
  sodium_mg_per_100g numeric,                             -- 0204, milligrams (OFF reports grams, the Edge Function converts)
  serving_size_g    numeric,
  serving_label     text,
  raw               jsonb,
  cached_at         timestamptz NOT NULL DEFAULT now(),
  created_at        timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX zane_foods_source_idx ON public.zane_foods USING btree (source, source_id);

ALTER TABLE zane_foods ENABLE ROW LEVEL SECURITY;

CREATE POLICY "authenticated read foods"
  ON zane_foods FOR SELECT TO authenticated USING (true);

-- Personal barcode corrections. The shared zane_foods row is never mutated by
-- a user's correction; this overlay is applied only for its owner at search
-- time and therefore round-trips as personal data.
CREATE TABLE zane_food_barcode_overrides (
  user_id          uuid    NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  source           text    NOT NULL CHECK (source IN ('off')),
  source_id        text    NOT NULL CHECK (source_id ~ '^[0-9]{8,14}$'),
  food_name        text    NOT NULL,
  brand            text,
  kcal_per_100g    numeric NOT NULL CHECK (kcal_per_100g >= 0),
  protein_per_100g numeric NOT NULL CHECK (protein_per_100g >= 0),
  carbs_per_100g   numeric NOT NULL CHECK (carbs_per_100g >= 0),
  fat_per_100g     numeric NOT NULL CHECK (fat_per_100g >= 0),
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, source, source_id)
);

CREATE INDEX zane_food_barcode_overrides_user_idx
  ON public.zane_food_barcode_overrides USING btree (user_id, updated_at DESC);

ALTER TABLE zane_food_barcode_overrides ENABLE ROW LEVEL SECURITY;

CREATE POLICY "zane_food_barcode_overrides_own"
  ON zane_food_barcode_overrides FOR ALL TO authenticated
  USING ((select auth.uid()) = user_id)
  WITH CHECK ((select auth.uid()) = user_id);

CREATE TABLE zane_food_recipes (
  id          text        PRIMARY KEY,
  user_id     uuid        NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  name        text        NOT NULL,
  items       jsonb       NOT NULL DEFAULT '[]',
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  portions    integer     NOT NULL DEFAULT 1,  -- how many servings the batch in `items` splits into
  cooked_weight_g numeric                      -- 0228, optional: weight of the finished (cooked) dish, freely typed, never derived from items' raw grams
);

CREATE INDEX zane_food_recipes_user_idx ON public.zane_food_recipes USING btree (user_id, created_at DESC);

ALTER TABLE zane_food_recipes ENABLE ROW LEVEL SECURITY;

CREATE POLICY "zane_food_recipes_own"
  ON zane_food_recipes FOR ALL
