-- ── Feature map publish flow (Migration 0156) ──────────────────────────────

CREATE OR REPLACE FUNCTION public.publish_feature_map()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.email() IS DISTINCT FROM 'office@btc-prime.biz' THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  DELETE FROM zane_feature_map_published WHERE card_id IS NOT NULL;
  INSERT INTO zane_feature_map_published
    (card_id, hidden, is_custom, cat, name, role, summary, actions, sort, created_at, updated_at)
  SELECT card_id, hidden, is_custom, cat, name, role, summary, actions, sort, created_at, now()
  FROM zane_feature_map;
END;
$function$;

REVOKE EXECUTE ON FUNCTION public.publish_feature_map() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.publish_feature_map() TO authenticated;

CREATE OR REPLACE FUNCTION public.discard_feature_map()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.email() IS DISTINCT FROM 'office@btc-prime.biz' THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  DELETE FROM zane_feature_map WHERE card_id IS NOT NULL;
  INSERT INTO zane_feature_map
    (card_id, hidden, is_custom, cat, name, role, summary, actions, sort, created_at, updated_at)
  SELECT card_id, hidden, is_custom, cat, name, role, summary, actions, sort, created_at, now()
  FROM zane_feature_map_published;
END;
$function$;

REVOKE EXECUTE ON FUNCTION public.discard_feature_map() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.discard_feature_map() TO authenticated;

-- Login-free read of the published feature map (public page + all users). Hidden
-- custom cards are withheld; hidden catalog-card flags are returned. anon is
-- granted execute here by design.
CREATE OR REPLACE FUNCTION public.get_public_feature_map()
 RETURNS TABLE (card_id text, hidden boolean, is_custom boolean, cat text, name text, role text, summary text, actions jsonb, sort int)
 LANGUAGE sql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT card_id, hidden, is_custom, cat, name, role, summary, actions, sort
  FROM zane_feature_map_published
  WHERE NOT (is_custom AND hidden);
$function$;

REVOKE EXECUTE ON FUNCTION public.get_public_feature_map() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_public_feature_map() TO anon, authenticated;

-- Founding-seat count for the login-free landing page (welcome.html). Returns
-- three aggregates and nothing per-account. anon is granted execute by design;
-- this is the second such function. The seat definition mirrors
-- grant_lifetime_if_qualified() and must stay in step with it. Migration 0244.
CREATE OR REPLACE FUNCTION public.get_founding_seats()
 RETURNS TABLE (total int, taken int, remaining int)
 LANGUAGE sql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT t.total,
         s.taken,
         GREATEST(t.total - s.taken, 0) AS remaining
    FROM (SELECT COALESCE((SELECT lifetime_seats_total FROM zane_app_config WHERE id = 1), 75)::int AS total) t,
         (SELECT COUNT(*)::int AS taken FROM zane_profiles WHERE tier = 'lifetime') s;
$function$;

REVOKE EXECUTE ON FUNCTION public.get_founding_seats() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_founding_seats() TO anon, authenticated;

-- ── Ops: schema inventory for the db-drift workflow (Migrations 0142, 0258) ─

CREATE OR REPLACE FUNCTION public.admin_schema_inventory()
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT jsonb_build_object(
    'columns', (
      SELECT jsonb_agg(jsonb_build_object('t', table_name, 'c', column_name)
                       ORDER BY table_name, ordinal_position)
      FROM information_schema.columns
      WHERE table_schema = 'public'
    ),
    'functions', (
      SELECT jsonb_agg(jsonb_build_object(
               'f', p.proname,
               'sig', p.oid::regprocedure::text,
               'anon_exec', has_function_privilege('anon', p.oid, 'execute'),
               'authenticated_exec', has_function_privilege('authenticated', p.oid, 'execute'),
               'definer', p.prosecdef)
             ORDER BY p.proname)
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE n.nspname = 'public'
    ),
    'realtime', (
      SELECT COALESCE(jsonb_agg(tablename ORDER BY tablename), '[]'::jsonb)
      FROM pg_publication_tables
      WHERE pubname = 'supabase_realtime'
    )
  );
$$;

REVOKE EXECUTE ON FUNCTION public.admin_schema_inventory() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.admin_schema_inventory() TO service_role;

-- All-time top-N exercises by session-entry count (Migration 0195). The client
-- only ever holds session.entries for the 70-day boot window plus whatever old
-- sessions happen to be cached from unrelated detail-view visits, so counting
-- entries locally under-counts for older accounts.
CREATE OR REPLACE FUNCTION public.get_top_exercises(p_user_id uuid DEFAULT NULL, p_limit int DEFAULT 5)
 RETURNS TABLE(ex_id text, session_count bigint)
 LANGUAGE sql STABLE SECURITY INVOKER SET search_path TO 'public'
AS $function$
  WITH uid AS (SELECT COALESCE(p_user_id, auth.uid()) AS id)
  SELECT e.ex_id, COUNT(*) AS session_count
  FROM zane_session_entries e
  JOIN zane_sessions s ON s.id = e.session_id
  WHERE e.user_id = (SELECT id FROM uid)
    AND e.ex_id IS NOT NULL
    AND s.ended IS NOT NULL
  GROUP BY e.ex_id
  ORDER BY session_count DESC
  LIMIT GREATEST(p_limit, 1);
$function$;

REVOKE EXECUTE ON FUNCTION public.get_top_exercises(uuid, int) FROM PUBLIC, anon;
GRANT  EXECUTE ON FUNCTION public.get_top_exercises(uuid, int) TO authenticated;

-- ── Edge Function usage quota (migration 0207) ──────────────────────────────
-- Per-user, per-day call counter for the food Edge Functions (search-foods,
-- scan-label, scan-label-claude), which otherwise had auth as their only gate
-- while fanning out to third-party APIs and a vision model. RLS on with NO
-- policies (same shape as zane_recipe_shares): reachable only through
-- bump_api_usage below, which is granted to service_role alone. Advisory: the
-- Edge Functions fail open if the RPC errors, so the quota can never block
-- someone from logging food.

CREATE TABLE zane_api_usage (
  user_id    uuid        NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  day        date        NOT NULL DEFAULT current_date,
  kind       text        NOT NULL,              -- 'search' | 'scan'
  count      integer     NOT NULL DEFAULT 0,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, day, kind)
);

ALTER TABLE zane_api_usage ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.bump_api_usage(p_user_id uuid, p_kind text, p_limit integer)
 RETURNS boolean
 LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer;
BEGIN
  INSERT INTO public.zane_api_usage (user_id, day, kind, count, updated_at)
  VALUES (p_user_id, current_date, p_kind, 1, now())
  ON CONFLICT (user_id, day, kind)
    DO UPDATE SET count = public.zane_api_usage.count + 1, updated_at = now()
  RETURNING count INTO v_count;
  RETURN v_count <= p_limit;
END;
$function$;

-- Migration 0208: REVOKE FROM PUBLIC is not enough on its own here. An ALTER
-- DEFAULT PRIVILEGES rule owned by postgres grants EXECUTE on every new
-- function to authenticated (0132 removed the equivalent anon rule, not this
-- one), and this function takes p_user_id as a plain argument with no auth
-- check of its own, so any signed-in user could otherwise run another user's
-- counter over the limit and lock them out for the day.
REVOKE EXECUTE ON FUNCTION public.bump_api_usage(uuid, text, integer) FROM PUBLIC, authenticated;
GRANT  EXECUTE ON FUNCTION public.bump_api_usage(uuid, text, integer) TO service_role;
-- Social foundation: friends, groups, messages, privacy and plan snapshots.
-- Friends deliberately do not reuse zane_coaching: coaching is an asymmetric
-- relationship with broad client-data access, while friends are opt-in and
-- metric-specific.

ALTER TABLE public.zane_user_settings
  ADD COLUMN IF NOT EXISTS show_friends_tab boolean NOT NULL DEFAULT false;

CREATE TABLE public.zane_social_profiles (
  user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  handle text UNIQUE,
  friend_code text NOT NULL UNIQUE DEFAULT upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10)),
  steps_visible boolean NOT NULL DEFAULT false,
  workouts_visible boolean NOT NULL DEFAULT false,
  adherence_visible boolean NOT NULL DEFAULT false,
  metric_visibility jsonb NOT NULL DEFAULT '{"steps":false,"workouts":false,"adherence":false,"calories":false,"protein":false,"carbs":false,"fat":false,"fiber":false,"water":false,"cardioMinutes":false,"cardioDistance":false,"weight":false,"bodyFatPct":false,"waistCm":false,"hipsCm":false,"chestCm":false,"armCm":false,"thighCm":false,"calfCm":false,"glucose":false,"bloodPressure":false,"bodyTemp":false}'::jsonb,
  metric_slots jsonb NOT NULL DEFAULT '["steps","workouts","adherence"]'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT zane_social_profiles_handle_check CHECK (handle IS NULL OR handle ~ '^[a-z0-9_]{3,20}$')
);

CREATE TABLE public.zane_social_friendships (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  requester_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  addressee_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'accepted')),
  accepted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT zane_social_friendships_not_self CHECK (requester_id <> addressee_id),
  CONSTRAINT zane_social_friendships_pair UNIQUE (requester_id, addressee_id)
);

CREATE TABLE public.zane_social_blocks (
  blocker_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  blocked_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (blocker_id, blocked_id),
  CONSTRAINT zane_social_blocks_not_self CHECK (blocker_id <> blocked_id)
);

CREATE TABLE public.zane_social_groups (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  owner_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  name text NOT NULL CHECK (char_length(trim(name)) BETWEEN 1 AND 60),
  join_code text NOT NULL UNIQUE DEFAULT upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10)),
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.zane_social_group_members (
  group_id uuid NOT NULL REFERENCES public.zane_social_groups(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  role text NOT NULL DEFAULT 'member' CHECK (role IN ('owner', 'member')),
  joined_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (group_id, user_id)
);

CREATE TABLE public.zane_social_messages (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sender_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  recipient_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,
  group_id uuid REFERENCES public.zane_social_groups(id) ON DELETE CASCADE,
  body text NOT NULL DEFAULT '' CHECK (char_length(body) <= 4000),
  created_at timestamptz NOT NULL DEFAULT now(),
  edited_at timestamptz,
  CONSTRAINT zane_social_messages_target_check CHECK ((recipient_id IS NOT NULL) <> (group_id IS NOT NULL)),
  CONSTRAINT zane_social_messages_content_check CHECK (char_length(body) > 0)
);

CREATE TABLE public.zane_social_message_attachments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  message_id uuid NOT NULL REFERENCES public.zane_social_messages(id) ON DELETE CASCADE,
  uploaded_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  storage_path text NOT NULL UNIQUE,
  file_name text NOT NULL,
  mime_type text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.zane_social_message_reads (
  message_id uuid NOT NULL REFERENCES public.zane_social_messages(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  read_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (message_id, user_id)
);

CREATE TABLE public.zane_social_plan_shares (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sender_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  recipient_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,
  group_id uuid REFERENCES public.zane_social_groups(id) ON DELETE CASCADE,
  plan_name text NOT NULL CHECK (char_length(trim(plan_name)) BETWEEN 1 AND 120),
  snapshot jsonb NOT NULL CHECK (jsonb_typeof(snapshot) = 'object'),
  created_at timestamptz NOT NULL DEFAULT now(),
  imported_at timestamptz,
  CONSTRAINT zane_social_plan_shares_target_check CHECK ((recipient_id IS NOT NULL AND group_id IS NULL) OR (recipient_id IS NULL AND group_id IS NOT NULL))
);

CREATE TABLE public.zane_social_plan_share_imports (
  share_id uuid NOT NULL REFERENCES public.zane_social_plan_shares(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  imported_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (share_id, user_id)
);

CREATE TABLE public.zane_social_reports (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  reporter_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  target_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  message_id uuid REFERENCES public.zane_social_messages(id) ON DELETE SET NULL,
  group_id uuid REFERENCES public.zane_social_groups(id) ON DELETE SET NULL,
  reason text NOT NULL CHECK (reason IN ('spam', 'harassment', 'unsafe', 'other')),
  details text NOT NULL DEFAULT '' CHECK (char_length(details) <= 2000),
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'reviewed', 'closed')),
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT zane_social_reports_target_check CHECK (target_user_id IS NOT NULL OR message_id IS NOT NULL OR group_id IS NOT NULL)
);

CREATE TABLE public.zane_social_workout_comments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id text NOT NULL REFERENCES public.zane_sessions(id) ON DELETE CASCADE,
  author_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  kind text NOT NULL DEFAULT 'comment' CHECK (kind IN ('comment', 'cheer')),
  body text NOT NULL CHECK (char_length(trim(body)) BETWEEN 1 AND 400),
  created_at timestamptz NOT NULL DEFAULT now()
);

-- Server-only idempotency ledger for Friends push delivery. This is derived
-- provider state, not user content, and is intentionally excluded from user
-- backups.
CREATE TABLE public.zane_social_notification_deliveries (
  event_key        text NOT NULL,
  recipient_id     uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  event_kind       text NOT NULL,
  last_attempt_at  timestamptz,
  delivered_at     timestamptz,
  created_at       timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT zane_social_notification_deliveries_pkey PRIMARY KEY (event_key, recipient_id),
  CONSTRAINT zane_social_notification_deliveries_kind_check
    CHECK (event_kind = ANY (ARRAY['message'::text, 'friend_request'::text, 'finished_workout_comment'::text, 'friend_started'::text]))
);

CREATE INDEX zane_social_notification_deliveries_recipient_idx
  ON public.zane_social_notification_deliveries(recipient_id, delivered_at);

-- Server-only rate state for the notification Edge Function. This table is
-- derived operational state, not user content, and has no client policies.
-- Per-caller invite throttle for invite_client(). Bookkeeping only, never read
-- by a client: the function is SECURITY DEFINER and the table has RLS on with
-- no policies. Counted on every attempt including misses, since enumeration is
-- built out of misses.
CREATE TABLE IF NOT EXISTS public.zane_invite_attempts (
  caller_id         uuid        PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  window_started_at timestamptz NOT NULL DEFAULT now(),
  attempts          integer     NOT NULL DEFAULT 0
);
ALTER TABLE public.zane_invite_attempts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.zane_invite_attempts FROM PUBLIC, anon, authenticated;

CREATE TABLE public.zane_social_notification_attempts (
  caller_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  window_started_at timestamptz NOT NULL DEFAULT now(),
  attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0)
);

ALTER TABLE public.zane_social_notification_attempts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.zane_social_notification_attempts FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.zane_social_notification_attempts TO service_role;

CREATE INDEX zane_social_friendships_addressee_idx ON public.zane_social_friendships(addressee_id, status);
CREATE INDEX zane_social_friendships_requester_idx ON public.zane_social_friendships(requester_id, status);
CREATE INDEX zane_social_group_members_user_idx ON public.zane_social_group_members(user_id, group_id);
CREATE INDEX zane_social_messages_direct_idx ON public.zane_social_messages(recipient_id, created_at DESC);
CREATE INDEX zane_social_messages_group_idx ON public.zane_social_messages(group_id, created_at DESC);
CREATE INDEX zane_social_message_attachments_message_idx ON public.zane_social_message_attachments(message_id);
CREATE INDEX zane_social_reports_status_idx ON public.zane_social_reports(status, created_at DESC);
CREATE INDEX zane_social_workout_comments_session_idx ON public.zane_social_workout_comments(session_id, created_at);
CREATE INDEX zane_social_workout_comments_author_idx ON public.zane_social_workout_comments(author_id, created_at DESC);
CREATE UNIQUE INDEX zane_social_friendships_canonical_pair_idx
  ON public.zane_social_friendships (LEAST(requester_id, addressee_id), GREATEST(requester_id, addressee_id));

-- Existing accounts receive a stable code immediately. New accounts are
-- created by the auth trigger below, before the client has loaded its store.
INSERT INTO public.zane_social_profiles (user_id)
SELECT p.id FROM public.zane_profiles p
ON CONFLICT (user_id) DO NOTHING;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.zane_user_settings (user_id) VALUES (new.id)
  ON CONFLICT DO NOTHING;
  INSERT INTO public.zane_social_profiles (user_id) VALUES (new.id)
  ON CONFLICT DO NOTHING;
  RETURN new;
END;
$function$;

-- Migration 0284: social audit follow-up.
CREATE OR REPLACE FUNCTION public.social_update_metric_preferences(
  p_metric_visibility jsonb DEFAULT '{}'::jsonb,
  p_metric_slots jsonb DEFAULT NULL::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_profile public.zane_social_profiles;
  v_input jsonb := CASE
    WHEN jsonb_typeof(coalesce(p_metric_visibility, '{}'::jsonb)) = 'object' THEN p_metric_visibility
    ELSE '{}'::jsonb
  END;
  v_existing jsonb;
  v_visibility jsonb;
  v_slots jsonb;
  v_allowed text[] := ARRAY[
    'steps','workouts','adherence','calories','protein','carbs','fat','fiber',
    'water','cardioMinutes','cardioDistance','weight','bodyFatPct','waistCm',
    'hipsCm','chestCm','armCm','thighCm','calfCm','glucose','bloodPressure','bodyTemp'
  ];
  v_slot_count integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  INSERT INTO public.zane_social_profiles (user_id) VALUES (v_uid) ON CONFLICT (user_id) DO NOTHING;
  SELECT * INTO v_profile FROM public.zane_social_profiles WHERE user_id = v_uid;
  v_existing := coalesce(v_profile.metric_visibility, '{}'::jsonb);
  SELECT jsonb_object_agg(item.key, to_jsonb(lower(coalesce(v_input ->> item.key, v_existing ->> item.key, 'false')) = 'true'))
    INTO v_visibility FROM unnest(v_allowed) AS item(key);
  v_slots := coalesce(p_metric_slots, v_profile.metric_slots, '["steps","workouts","adherence"]'::jsonb);
  IF jsonb_typeof(v_slots) <> 'array' THEN
    v_slots := '["steps","workouts","adherence"]'::jsonb;
  ELSE
    SELECT count(DISTINCT value) INTO v_slot_count FROM jsonb_array_elements_text(v_slots) AS item(value);
    IF jsonb_array_length(v_slots) <> 3 OR v_slot_count <> 3 OR EXISTS (
      SELECT 1 FROM jsonb_array_elements_text(v_slots) AS item(value) WHERE NOT (item.value = ANY(v_allowed))
    ) THEN v_slots := '["steps","workouts","adherence"]'::jsonb; END IF;
  END IF;
  UPDATE public.zane_social_profiles
  SET steps_visible = (v_visibility->>'steps')::boolean,
      workouts_visible = (v_visibility->>'workouts')::boolean,
      adherence_visible = (v_visibility->>'adherence')::boolean,
      metric_visibility = v_visibility, metric_slots = v_slots, updated_at = now()
  WHERE user_id = v_uid RETURNING * INTO v_profile;
  RETURN jsonb_build_object(
    'userId', v_profile.user_id, 'handle', v_profile.handle, 'friendCode', v_profile.friend_code,
    'stepsVisible', v_profile.steps_visible, 'workoutsVisible', v_profile.workouts_visible,
    'adherenceVisible', v_profile.adherence_visible, 'metricVisibility', v_profile.metric_visibility,
    'metricSlots', v_profile.metric_slots
  );
END;
$function$;
REVOKE EXECUTE ON FUNCTION public.social_update_metric_preferences(jsonb, jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.social_update_metric_preferences(jsonb, jsonb) TO authenticated;

CREATE OR REPLACE FUNCTION public.delete_my_social_data()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  DELETE FROM public.zane_social_notification_deliveries WHERE recipient_id = v_uid;
  DELETE FROM public.zane_social_notification_attempts WHERE caller_id = v_uid;
  DELETE FROM public.zane_social_reports
  WHERE reporter_id = v_uid OR (target_user_id = v_uid AND message_id IS NULL AND group_id IS NULL);
  UPDATE public.zane_social_reports SET target_user_id = NULL WHERE target_user_id = v_uid;
  DELETE FROM public.zane_social_message_reads WHERE user_id = v_uid;
  DELETE FROM public.zane_social_plan_share_imports WHERE user_id = v_uid;
  DELETE FROM public.zane_social_plan_shares
  WHERE sender_id = v_uid OR recipient_id = v_uid
     OR group_id IN (SELECT id FROM public.zane_social_groups WHERE owner_id = v_uid);
  DELETE FROM public.zane_social_messages
  WHERE sender_id = v_uid OR recipient_id = v_uid
     OR group_id IN (SELECT id FROM public.zane_social_groups WHERE owner_id = v_uid);
  DELETE FROM public.zane_social_groups WHERE owner_id = v_uid;
  DELETE FROM public.zane_social_group_members WHERE user_id = v_uid;
  DELETE FROM public.zane_social_friendships WHERE requester_id = v_uid OR addressee_id = v_uid;
  DELETE FROM public.zane_social_blocks WHERE blocker_id = v_uid OR blocked_id = v_uid;
  DELETE FROM public.zane_social_workout_comments WHERE author_id = v_uid;
  DELETE FROM public.zane_social_message_attachments WHERE uploaded_by = v_uid;
  DELETE FROM public.zane_social_profiles WHERE user_id = v_uid;
END;
$function$;
REVOKE EXECUTE ON FUNCTION public.delete_my_social_data() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.delete_my_social_data() TO authenticated;

-- Exact-handle/code lookup returns only the public identity fields needed for
-- an add flow. Privacy flags and health data never leave this function.
CREATE OR REPLACE FUNCTION public.social_lookup_profile(p_query text)
 RETURNS TABLE(user_id uuid, handle text, display_name text, friend_code text, relationship text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_query text := lower(trim(replace(coalesce(p_query, ''), '@', '')));
BEGIN
  IF v_uid IS NULL OR v_query = '' THEN RETURN; END IF;
  RETURN QUERY
  SELECT sp.user_id, sp.handle, coalesce(p.name, 'Zane athlete'), sp.friend_code,
    CASE
      WHEN EXISTS (SELECT 1 FROM zane_social_friendships f WHERE f.status = 'accepted' AND ((f.requester_id = v_uid AND f.addressee_id = sp.user_id) OR (f.requester_id = sp.user_id AND f.addressee_id = v_uid))) THEN 'friends'
      WHEN EXISTS (SELECT 1 FROM zane_social_friendships f WHERE f.status = 'pending' AND f.requester_id = v_uid AND f.addressee_id = sp.user_id) THEN 'outgoing'
      WHEN EXISTS (SELECT 1 FROM zane_social_friendships f WHERE f.status = 'pending' AND f.requester_id = sp.user_id AND f.addressee_id = v_uid) THEN 'incoming'
      ELSE 'none'
    END
  FROM zane_social_profiles sp
  LEFT JOIN zane_profiles p ON p.id = sp.user_id
  WHERE sp.user_id <> v_uid
    AND NOT EXISTS (SELECT 1 FROM zane_social_blocks b WHERE (b.blocker_id = v_uid AND b.blocked_id = sp.user_id) OR (b.blocker_id = sp.user_id AND b.blocked_id = v_uid))
    AND (lower(coalesce(sp.handle, '')) = v_query OR lower(sp.friend_code) = v_query)
  LIMIT 1;
END;
$function$;

DROP FUNCTION IF EXISTS public.social_get_dashboard(date);


CREATE OR REPLACE FUNCTION public.social_send_friend_request(p_target_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_id uuid;
BEGIN
  IF v_uid IS NULL OR p_target_id IS NULL OR v_uid = p_target_id THEN RAISE EXCEPTION 'Invalid friend target'; END IF;
  IF NOT EXISTS (SELECT 1 FROM zane_social_profiles WHERE user_id = p_target_id) THEN RAISE EXCEPTION 'User not found'; END IF;
  IF EXISTS (SELECT 1 FROM zane_social_blocks b WHERE (b.blocker_id = v_uid AND b.blocked_id = p_target_id) OR (b.blocker_id = p_target_id AND b.blocked_id = v_uid)) THEN RAISE EXCEPTION 'User unavailable'; END IF;
  IF EXISTS (SELECT 1 FROM zane_social_friendships f WHERE ((f.requester_id = v_uid AND f.addressee_id = p_target_id) OR (f.requester_id = p_target_id AND f.addressee_id = v_uid)) AND f.status IN ('pending', 'accepted')) THEN RAISE EXCEPTION 'Friend request already exists'; END IF;
  INSERT INTO zane_social_friendships (requester_id, addressee_id) VALUES (v_uid, p_target_id) RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$;


CREATE OR REPLACE FUNCTION public.social_remove_friend(p_target_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  DELETE FROM zane_social_friendships
  WHERE status = 'accepted' AND ((requester_id = auth.uid() AND addressee_id = p_target_id) OR (requester_id = p_target_id AND addressee_id = auth.uid()));
END;
$function$;


CREATE OR REPLACE FUNCTION public.social_create_group(p_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF auth.uid() IS NULL OR char_length(trim(coalesce(p_name, ''))) = 0 THEN RAISE EXCEPTION 'Group name required'; END IF;
  INSERT INTO zane_social_groups (owner_id, name) VALUES (auth.uid(), trim(p_name)) RETURNING id INTO v_id;
  INSERT INTO zane_social_group_members (group_id, user_id, role) VALUES (v_id, auth.uid(), 'owner');
  RETURN v_id;
END;
$function$;


CREATE OR REPLACE FUNCTION public.social_leave_group(p_group_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM zane_social_groups WHERE id = p_group_id AND owner_id = auth.uid()) THEN RAISE EXCEPTION 'Owner cannot leave group'; END IF;
  DELETE FROM zane_social_group_members WHERE group_id = p_group_id AND user_id = auth.uid();
END;
$function$;

CREATE OR REPLACE FUNCTION public.social_delete_group(p_group_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  DELETE FROM zane_social_groups
  WHERE id = p_group_id AND owner_id = v_uid;
  IF NOT FOUND THEN RAISE EXCEPTION 'Only the group owner can delete this group'; END IF;
END;
$function$;





CREATE OR REPLACE FUNCTION public.social_delete_plan_share(p_share_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  DELETE FROM zane_social_plan_shares
  WHERE id = p_share_id AND (sender_id = v_uid OR (group_id IS NULL AND recipient_id = v_uid));
  IF NOT FOUND THEN RAISE EXCEPTION 'Plan share not found'; END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.social_report(p_target_user_id uuid, p_message_id uuid, p_group_id uuid, p_reason text, p_details text DEFAULT '')
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF auth.uid() IS NULL OR p_reason NOT IN ('spam', 'harassment', 'unsafe', 'other') THEN RAISE EXCEPTION 'Invalid report'; END IF;
  INSERT INTO zane_social_reports (reporter_id, target_user_id, message_id, group_id, reason, details)
  VALUES (auth.uid(), p_target_user_id, p_message_id, p_group_id, p_reason, left(coalesce(p_details, ''), 2000))
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$;

