CREATE OR REPLACE FUNCTION public.admin_set_coaching_transport(p_transport text)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE
  v_transport text := lower(trim(COALESCE(p_transport, '')));
  v_table text;
BEGIN
  IF lower(COALESCE((SELECT auth.email()), '')) <> 'office@btc-prime.biz' THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF v_transport NOT IN ('legacy', 'broadcast') THEN
    RAISE EXCEPTION 'Invalid coaching transport';
  END IF;

  IF v_transport = 'legacy' THEN
    ALTER TABLE public.zane_coaching REPLICA IDENTITY FULL;
    FOREACH v_table IN ARRAY ARRAY[
      'zane_coaching',
      'zane_coaching_notes',
      'zane_user_settings',
      'zane_checkins'
    ]
    LOOP
      IF NOT EXISTS (
        SELECT 1
        FROM pg_catalog.pg_publication_tables pt
        WHERE pt.pubname = 'supabase_realtime'
          AND pt.schemaname = 'public'
          AND pt.tablename = v_table
      ) THEN
        EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', v_table);
      END IF;
    END LOOP;
  END IF;

  INSERT INTO public.zane_app_config (id, coaching_transport)
  VALUES (1, v_transport)
  ON CONFLICT (id) DO UPDATE
  SET coaching_transport = EXCLUDED.coaching_transport;

  RETURN v_transport;
END;
$function$;

CREATE OR REPLACE FUNCTION public.db_health()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE
  v_connections integer;
  v_max_connections integer := current_setting('max_connections')::integer;
  v_waiting integer;
  v_long_running integer;
  v_net_response_bytes bigint := 0;
  v_critical boolean;
BEGIN
  SELECT count(*)::integer
    INTO v_connections
  FROM pg_catalog.pg_stat_activity
  WHERE datname = current_database();

  SELECT count(*)::integer
    INTO v_waiting
  FROM pg_catalog.pg_stat_activity
  WHERE datname = current_database()
    AND pid <> pg_backend_pid()
    AND backend_type = 'client backend'
    AND state = 'active'
    AND wait_event_type IS NOT NULL;

  SELECT count(*)::integer
    INTO v_long_running
  FROM pg_catalog.pg_stat_activity
  WHERE datname = current_database()
    AND pid <> pg_backend_pid()
    AND backend_type = 'client backend'
    AND state = 'active'
    AND query_start < clock_timestamp() - interval '5 seconds';

  IF to_regclass('net._http_response') IS NOT NULL THEN
    v_net_response_bytes := pg_catalog.pg_total_relation_size('net._http_response'::regclass);
  END IF;

  v_critical := v_connections >= 45 OR v_waiting > 0 OR v_long_running > 0;

  RETURN jsonb_build_object(
    'ok', NOT v_critical,
    'checkedAt', clock_timestamp(),
    'connections', v_connections,
    'maxConnections', v_max_connections,
    'connectionRatio', round(v_connections::numeric / GREATEST(v_max_connections, 1), 4),
    'waitingQueries', v_waiting,
    'longRunningQueries', v_long_running,
    'pgNetResponseBytes', v_net_response_bytes
  );
END;
$function$;

