CREATE POLICY "coaching users receive own invalidations"
ON realtime.messages
FOR SELECT
TO authenticated
USING (
  extension = 'broadcast'
  AND (SELECT realtime.topic()) = 'coaching:user:' || (SELECT auth.uid())::text
);

CREATE OR REPLACE FUNCTION app_private.broadcast_coaching_user(
  p_user_id uuid,
  p_resource text
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
BEGIN
  IF p_user_id IS NULL OR p_resource NOT IN ('relationships', 'notes', 'support', 'status') THEN
    RETURN;
  END IF;

  BEGIN
    PERFORM realtime.send(
      jsonb_build_object('resource', p_resource),
      'coaching_invalidate',
      'coaching:user:' || p_user_id::text,
      true
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Coaching Broadcast invalidation failed for resource %', p_resource;
  END;
END;
$function$;

CREATE OR REPLACE FUNCTION app_private.broadcast_coaching_change()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE
  v_row jsonb := CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
  v_coaching public.zane_coaching%ROWTYPE;
  v_resource text;
  v_user_id uuid;
  v_coach_id uuid;
  v_client_id uuid;
BEGIN
  CASE TG_TABLE_NAME
    WHEN 'zane_coaching' THEN
      v_resource := CASE WHEN (v_row->>'id') LIKE 'support_%' THEN 'support' ELSE 'relationships' END;
      v_coach_id := (v_row->>'coach_id')::uuid;
      v_client_id := (v_row->>'client_id')::uuid;
      PERFORM app_private.broadcast_coaching_user(v_coach_id, v_resource);
      IF v_client_id IS DISTINCT FROM v_coach_id THEN
        PERFORM app_private.broadcast_coaching_user(v_client_id, v_resource);
      END IF;

      IF TG_OP = 'UPDATE' THEN
        IF (v_old->>'coach_id') IS DISTINCT FROM (v_new->>'coach_id')
           AND (v_old->>'coach_id')::uuid IS DISTINCT FROM v_client_id THEN
          PERFORM app_private.broadcast_coaching_user((v_old->>'coach_id')::uuid, v_resource);
        END IF;
        IF (v_old->>'client_id') IS DISTINCT FROM (v_new->>'client_id')
           AND (v_old->>'client_id')::uuid IS DISTINCT FROM v_coach_id THEN
          PERFORM app_private.broadcast_coaching_user((v_old->>'client_id')::uuid, v_resource);
        END IF;
      END IF;

    WHEN 'zane_coaching_notes' THEN
      SELECT * INTO v_coaching
      FROM public.zane_coaching c
      WHERE c.id = v_row->>'coaching_id';
      IF FOUND THEN
        v_resource := CASE WHEN v_coaching.id LIKE 'support_%' THEN 'support' ELSE 'notes' END;
        PERFORM app_private.broadcast_coaching_user(v_coaching.coach_id, v_resource);
        IF v_coaching.client_id IS DISTINCT FROM v_coaching.coach_id THEN
          PERFORM app_private.broadcast_coaching_user(v_coaching.client_id, v_resource);
        END IF;
      END IF;

    WHEN 'zane_user_settings' THEN
      IF (v_new->'in_progress_session_id') IS NOT DISTINCT FROM (v_old->'in_progress_session_id')
         AND (v_new->'status_mode') IS NOT DISTINCT FROM (v_old->'status_mode')
         AND (v_new->'status_mode_since') IS NOT DISTINCT FROM (v_old->'status_mode_since') THEN
        RETURN NEW;
      END IF;

      FOR v_user_id IN
        SELECT DISTINCT c.coach_id
        FROM public.zane_coaching c
        WHERE c.client_id = (v_new->>'user_id')::uuid
          AND c.coach_id <> c.client_id
          AND c.status = 'active'
          AND c.id NOT LIKE 'support_%'
      LOOP
        PERFORM app_private.broadcast_coaching_user(v_user_id, 'status');
      END LOOP;

    WHEN 'zane_checkins' THEN
      SELECT c.coach_id INTO v_user_id
      FROM public.zane_coaching c
      WHERE c.id = v_row->>'coaching_id'
        AND c.coach_id <> c.client_id
        AND c.status = 'active'
        AND c.id NOT LIKE 'support_%';
      IF FOUND THEN
        PERFORM app_private.broadcast_coaching_user(v_user_id, 'status');
      END IF;
  END CASE;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$;

REVOKE EXECUTE ON FUNCTION app_private.broadcast_coaching_user(uuid, text) FROM PUBLIC, anon, authenticated, service_role;
REVOKE EXECUTE ON FUNCTION app_private.broadcast_coaching_change() FROM PUBLIC, anon, authenticated, service_role;

DROP TRIGGER IF EXISTS zane_coaching_broadcast_invalidate ON public.zane_coaching;
CREATE TRIGGER zane_coaching_broadcast_invalidate
AFTER INSERT OR UPDATE OR DELETE ON public.zane_coaching
FOR EACH ROW EXECUTE FUNCTION app_private.broadcast_coaching_change();

DROP TRIGGER IF EXISTS zane_coaching_notes_broadcast_invalidate ON public.zane_coaching_notes;
CREATE TRIGGER zane_coaching_notes_broadcast_invalidate
AFTER INSERT OR UPDATE OR DELETE ON public.zane_coaching_notes
FOR EACH ROW EXECUTE FUNCTION app_private.broadcast_coaching_change();

DROP TRIGGER IF EXISTS zane_user_settings_coaching_broadcast_invalidate ON public.zane_user_settings;
CREATE TRIGGER zane_user_settings_coaching_broadcast_invalidate
AFTER UPDATE OF in_progress_session_id, status_mode, status_mode_since ON public.zane_user_settings
FOR EACH ROW EXECUTE FUNCTION app_private.broadcast_coaching_change();

DROP TRIGGER IF EXISTS zane_checkins_coaching_broadcast_invalidate ON public.zane_checkins;
CREATE TRIGGER zane_checkins_coaching_broadcast_invalidate
AFTER INSERT OR UPDATE ON public.zane_checkins
FOR EACH ROW EXECUTE FUNCTION app_private.broadcast_coaching_change();

-- Friends audit hardening (Migration 20260815110000). These service-role-only
-- helpers keep notification authorization and rate state inside Postgres.
CREATE OR REPLACE FUNCTION public.social_take_notification_rate_limit(p_caller_id uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_window timestamptz; v_attempts integer;
BEGIN
  IF p_caller_id IS NULL THEN RETURN false; END IF;
  INSERT INTO public.zane_social_notification_attempts(caller_id, window_started_at, attempts)
  VALUES (p_caller_id, now(), 0) ON CONFLICT (caller_id) DO NOTHING;
  SELECT window_started_at, attempts INTO v_window, v_attempts
    FROM public.zane_social_notification_attempts WHERE caller_id = p_caller_id FOR UPDATE;
  IF v_window < now() - interval '1 hour' THEN
    DELETE FROM public.zane_social_notification_deliveries WHERE created_at < now() - interval '30 days';
  END IF;
  IF v_window < now() - interval '1 minute' THEN
    UPDATE public.zane_social_notification_attempts SET window_started_at = now(), attempts = 1 WHERE caller_id = p_caller_id;
    RETURN true;
  END IF;
  IF v_attempts >= 120 THEN RETURN false; END IF;
  UPDATE public.zane_social_notification_attempts SET attempts = v_attempts + 1 WHERE caller_id = p_caller_id;
  RETURN true;
END;
$function$;

CREATE OR REPLACE FUNCTION app_private.social_tab_enabled(p_user_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
  -- Defaults to FALSE, matching the column default: show_friends_tab is an
  -- opt-in preview flag, so "no row" means the user never turned Friends on
  -- and should not be pushed about it. handle_new_user creates a settings row
  -- for every account anyway, so this fallback is a belt-and-braces case.
  SELECT COALESCE(
    (SELECT us.show_friends_tab FROM public.zane_user_settings us WHERE us.user_id = p_user_id),
    false
  );
$function$;

REVOKE EXECUTE ON FUNCTION app_private.social_tab_enabled(uuid) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.social_can_notify_message(p_message_id uuid, p_recipient_id uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_sender uuid; v_recipient uuid; v_group uuid; v_created timestamptz;
BEGIN
  IF p_message_id IS NULL OR p_recipient_id IS NULL THEN RETURN false; END IF;
  IF NOT app_private.social_tab_enabled(p_recipient_id) THEN RETURN false; END IF;
  SELECT sender_id, recipient_id, group_id, created_at INTO v_sender, v_recipient, v_group, v_created FROM public.zane_social_messages WHERE id = p_message_id;
  IF NOT FOUND OR v_sender = p_recipient_id OR v_created < now() - interval '24 hours' THEN RETURN false; END IF;
  IF v_recipient IS NOT NULL THEN
    RETURN v_recipient = p_recipient_id
      AND EXISTS (SELECT 1 FROM public.zane_social_friendships f WHERE f.status = 'accepted' AND f.accepted_at IS NOT NULL AND f.accepted_at <= v_created AND ((f.requester_id = v_sender AND f.addressee_id = p_recipient_id) OR (f.requester_id = p_recipient_id AND f.addressee_id = v_sender)))
      AND NOT EXISTS (SELECT 1 FROM public.zane_social_blocks b WHERE (b.blocker_id = v_sender AND b.blocked_id = p_recipient_id) OR (b.blocker_id = p_recipient_id AND b.blocked_id = v_sender));
  END IF;
  IF v_group IS NULL THEN RETURN false; END IF;
  RETURN EXISTS (SELECT 1 FROM public.zane_social_group_members gm WHERE gm.group_id = v_group AND gm.user_id = p_recipient_id)
    AND NOT EXISTS (SELECT 1 FROM public.zane_social_group_members gm JOIN public.zane_social_blocks b ON (b.blocker_id = p_recipient_id AND b.blocked_id = gm.user_id) OR (b.blocker_id = gm.user_id AND b.blocked_id = p_recipient_id) WHERE gm.group_id = v_group AND gm.user_id <> p_recipient_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.social_can_notify_finished_comment(p_comment_id uuid, p_recipient_id uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_author uuid; v_created timestamptz; v_owner uuid; v_started timestamptz; v_ended timestamptz; v_visible boolean;
BEGIN
  IF p_comment_id IS NULL OR p_recipient_id IS NULL THEN RETURN false; END IF;
  IF NOT app_private.social_tab_enabled(p_recipient_id) THEN RETURN false; END IF;
  SELECT wc.author_id, wc.created_at, s.user_id, COALESCE(s.started_at, s.date::timestamptz), s.ended, sp.workouts_visible INTO v_author, v_created, v_owner, v_started, v_ended, v_visible
    FROM public.zane_social_workout_comments wc JOIN public.zane_sessions s ON s.id = wc.session_id JOIN public.zane_social_profiles sp ON sp.user_id = s.user_id WHERE wc.id = p_comment_id;
  IF NOT FOUND OR v_owner <> p_recipient_id OR v_author = p_recipient_id OR v_ended IS NULL OR v_created < v_ended OR v_created < now() - interval '7 days' OR NOT COALESCE(v_visible, false) THEN RETURN false; END IF;
  RETURN EXISTS (SELECT 1 FROM public.zane_social_friendships f WHERE f.status = 'accepted' AND f.accepted_at IS NOT NULL AND f.accepted_at <= v_started AND ((f.requester_id = p_recipient_id AND f.addressee_id = v_author) OR (f.requester_id = v_author AND f.addressee_id = p_recipient_id)))
    AND NOT EXISTS (SELECT 1 FROM public.zane_social_blocks b WHERE (b.blocker_id = p_recipient_id AND b.blocked_id = v_author) OR (b.blocker_id = v_author AND b.blocked_id = p_recipient_id));
END;
$function$;

CREATE OR REPLACE FUNCTION public.social_can_notify_friend_started(p_session_id text, p_recipient_id uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_owner uuid; v_started timestamptz; v_ended timestamptz; v_visible boolean;
BEGIN
  IF NULLIF(trim(p_session_id), '') IS NULL OR p_recipient_id IS NULL THEN RETURN false; END IF;
  IF NOT app_private.social_tab_enabled(p_recipient_id) THEN RETURN false; END IF;
  SELECT s.user_id, s.started_at, s.ended, sp.workouts_visible INTO v_owner, v_started, v_ended, v_visible FROM public.zane_sessions s JOIN public.zane_social_profiles sp ON sp.user_id = s.user_id WHERE s.id = p_session_id;
  IF NOT FOUND OR v_started IS NULL OR v_ended IS NOT NULL OR v_started < now() - interval '24 hours' OR v_owner = p_recipient_id OR NOT COALESCE(v_visible, false) THEN RETURN false; END IF;
  -- The sender's own switch counts here too: an opted-out user should not be
  -- broadcasting workout starts to other people's lock screens either.
  IF NOT app_private.social_tab_enabled(v_owner) THEN RETURN false; END IF;
  RETURN EXISTS (SELECT 1 FROM public.zane_social_friendships f WHERE f.status = 'accepted' AND f.accepted_at IS NOT NULL AND f.accepted_at <= v_started AND ((f.requester_id = v_owner AND f.addressee_id = p_recipient_id) OR (f.requester_id = p_recipient_id AND f.addressee_id = v_owner)))
    AND NOT EXISTS (SELECT 1 FROM public.zane_social_blocks b WHERE (b.blocker_id = v_owner AND b.blocked_id = p_recipient_id) OR (b.blocker_id = p_recipient_id AND b.blocked_id = v_owner));
END;
$function$;

CREATE OR REPLACE FUNCTION public.social_can_notify_friend_request(p_friendship_id uuid, p_recipient_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (SELECT 1 FROM public.zane_social_friendships f WHERE f.id = p_friendship_id AND f.addressee_id = p_recipient_id AND f.status = 'pending' AND NOT EXISTS (SELECT 1 FROM public.zane_social_blocks b WHERE (b.blocker_id = f.requester_id AND b.blocked_id = f.addressee_id) OR (b.blocker_id = f.addressee_id AND b.blocked_id = f.requester_id)));
$function$;

REVOKE EXECUTE ON FUNCTION public.social_take_notification_rate_limit(uuid) FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.social_can_notify_message(uuid, uuid) FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.social_can_notify_finished_comment(uuid, uuid) FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.social_can_notify_friend_started(text, uuid) FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.social_can_notify_friend_request(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.social_take_notification_rate_limit(uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.social_can_notify_message(uuid, uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.social_can_notify_finished_comment(uuid, uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.social_can_notify_friend_started(text, uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.social_can_notify_friend_request(uuid, uuid) TO service_role;

-- Lightweight request snapshot for the global Friend Request banner. The
-- complete Friends dashboard remains lazy and is not required to show a new
-- request after login, focus, or a relationship Broadcast invalidation.
CREATE OR REPLACE FUNCTION public.social_get_pending_friend_requests()
RETURNS TABLE(id uuid, user_id uuid, name text, handle text)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  PERFORM app_private.require_social_available();

  RETURN QUERY
  SELECT
    f.id,
    f.requester_id,
    COALESCE(p.name, 'Zane athlete'),
    sp.handle
  FROM public.zane_social_friendships f
  JOIN public.zane_social_profiles sp ON sp.user_id = f.requester_id
  LEFT JOIN public.zane_profiles p ON p.id = f.requester_id
  WHERE f.addressee_id = v_uid
    AND f.status = 'pending'
    AND NOT EXISTS (
      SELECT 1
      FROM public.zane_social_blocks b
      WHERE (b.blocker_id = v_uid AND b.blocked_id = f.requester_id)
         OR (b.blocker_id = f.requester_id AND b.blocked_id = v_uid)
    )
  ORDER BY f.created_at DESC
  LIMIT 100;
END;
$function$;

REVOKE EXECUTE ON FUNCTION public.social_get_pending_friend_requests() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.social_get_pending_friend_requests() TO authenticated;

-- Bound Social push fan-out at the database boundary. One Edge invocation now
-- resolves recipients, claims every delivery and finalizes every result in
-- batches instead of multiplying HTTP/PostgREST calls per recipient.

DROP FUNCTION IF EXISTS public.social_take_notification_rate_limit(uuid);

CREATE TABLE IF NOT EXISTS public.zane_notification_maintenance (
  id boolean PRIMARY KEY DEFAULT true CHECK (id),
  last_delivery_cleanup_at timestamptz NOT NULL DEFAULT '-infinity'::timestamptz
);
INSERT INTO public.zane_notification_maintenance(id) VALUES (true) ON CONFLICT (id) DO NOTHING;
ALTER TABLE public.zane_notification_maintenance ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.zane_notification_maintenance FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.social_take_notification_rate_limit(
  p_caller_id uuid,
  p_cost integer DEFAULT 1
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_window timestamptz;
  v_attempts integer;
  v_cost integer := GREATEST(1, LEAST(COALESCE(p_cost, 1), 60));
  v_cleanup_due boolean := false;
BEGIN
  IF p_caller_id IS NULL THEN RETURN false; END IF;
  INSERT INTO public.zane_social_notification_attempts(caller_id, window_started_at, attempts)
  VALUES (p_caller_id, now(), 0) ON CONFLICT (caller_id) DO NOTHING;
  SELECT window_started_at, attempts INTO v_window, v_attempts
    FROM public.zane_social_notification_attempts WHERE caller_id = p_caller_id FOR UPDATE;
  -- Maintenance is global, not tied to this caller's rate-limit window. A
  -- continuously active caller must not prevent delivery-ledger cleanup.
  IF pg_try_advisory_xact_lock(1786173915) THEN
    UPDATE public.zane_notification_maintenance
    SET last_delivery_cleanup_at = now()
    WHERE id = true
      AND last_delivery_cleanup_at < now() - interval '1 hour'
    RETURNING true INTO v_cleanup_due;
    IF COALESCE(v_cleanup_due, false) THEN
      DELETE FROM public.zane_social_notification_deliveries
      WHERE ctid IN (
        SELECT ctid
        FROM public.zane_social_notification_deliveries
        WHERE created_at < now() - interval '30 days'
          AND (last_attempt_at IS NULL OR last_attempt_at < now() - interval '2 minutes')
        ORDER BY created_at
        LIMIT 5000
      );
    END IF;
  END IF;
  IF v_window < now() - interval '1 minute' THEN
    UPDATE public.zane_social_notification_attempts
    SET window_started_at = now(), attempts = v_cost
    WHERE caller_id = p_caller_id;
    RETURN true;
  END IF;
  IF v_attempts + v_cost > 60 THEN RETURN false; END IF;
  UPDATE public.zane_social_notification_attempts
  SET attempts = v_attempts + v_cost
  WHERE caller_id = p_caller_id;
  RETURN true;
END;
$function$;

CREATE OR REPLACE FUNCTION public.social_pending_notification_recipients(
  p_event_key text,
  p_recipient_ids uuid[]
)
RETURNS TABLE(recipient_id uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT DISTINCT id
  FROM unnest(COALESCE(p_recipient_ids, ARRAY[]::uuid[])) AS ids(id)
  WHERE id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.zane_social_notification_deliveries delivery
      WHERE delivery.event_key = p_event_key
        AND delivery.recipient_id = id
        AND delivery.delivered_at IS NOT NULL
    )
  ORDER BY id;
$function$;

CREATE OR REPLACE FUNCTION public.social_notification_message_recipients(
  p_message_id uuid,
  p_caller_id uuid
)
RETURNS TABLE(recipient_id uuid)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_sender uuid;
  v_recipient uuid;
  v_group uuid;
  v_created timestamptz;
BEGIN
  SELECT m.sender_id, m.recipient_id, m.group_id, m.created_at
  INTO v_sender, v_recipient, v_group, v_created
  FROM public.zane_social_messages m
  WHERE m.id = p_message_id;

  IF NOT FOUND OR v_sender <> p_caller_id OR v_created < now() - interval '24 hours' THEN
    RETURN;
  END IF;

  IF v_recipient IS NOT NULL THEN
    RETURN QUERY
    SELECT v_recipient
    WHERE v_recipient <> v_sender
      AND app_private.social_tab_enabled(v_recipient)
      AND EXISTS (
        SELECT 1 FROM public.zane_social_friendships f
        WHERE f.status = 'accepted'
          AND f.accepted_at IS NOT NULL
          AND f.accepted_at <= v_created
          AND ((f.requester_id = v_sender AND f.addressee_id = v_recipient)
            OR (f.requester_id = v_recipient AND f.addressee_id = v_sender))
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.zane_social_blocks b
        WHERE (b.blocker_id = v_sender AND b.blocked_id = v_recipient)
           OR (b.blocker_id = v_recipient AND b.blocked_id = v_sender)
      );
    RETURN;
  END IF;

  IF v_group IS NULL THEN RETURN; END IF;
  RETURN QUERY
  SELECT gm.user_id
  FROM public.zane_social_group_members gm
  WHERE gm.group_id = v_group
    AND gm.user_id <> v_sender
    AND app_private.social_tab_enabled(gm.user_id)
    AND NOT EXISTS (
      SELECT 1
      FROM public.zane_social_group_members other_member
      JOIN public.zane_social_blocks b
        ON (b.blocker_id = gm.user_id AND b.blocked_id = other_member.user_id)
        OR (b.blocker_id = other_member.user_id AND b.blocked_id = gm.user_id)
      WHERE other_member.group_id = v_group
        AND other_member.user_id <> gm.user_id
    )
  ORDER BY gm.user_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.social_notification_friend_started_recipients(
  p_session_id text,
  p_caller_id uuid
)
RETURNS TABLE(recipient_id uuid)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_owner uuid;
  v_started timestamptz;
  v_ended timestamptz;
  v_visible boolean;
BEGIN
  SELECT s.user_id, s.started_at, s.ended, sp.workouts_visible
  INTO v_owner, v_started, v_ended, v_visible
  FROM public.zane_sessions s
  JOIN public.zane_social_profiles sp ON sp.user_id = s.user_id
  WHERE s.id = p_session_id;

  IF NOT FOUND OR v_owner <> p_caller_id OR v_started IS NULL OR v_ended IS NOT NULL
     OR v_started < now() - interval '24 hours' OR NOT COALESCE(v_visible, false)
     OR NOT app_private.social_tab_enabled(v_owner) THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH friends AS (
    SELECT CASE WHEN f.requester_id = v_owner THEN f.addressee_id ELSE f.requester_id END AS friend_id
    FROM public.zane_social_friendships f
    WHERE f.status = 'accepted'
      AND f.accepted_at IS NOT NULL
      AND f.accepted_at <= v_started
      AND (f.requester_id = v_owner OR f.addressee_id = v_owner)
  )
  SELECT DISTINCT friends.friend_id
  FROM friends
  WHERE friends.friend_id <> v_owner
    AND app_private.social_tab_enabled(friends.friend_id)
    AND NOT EXISTS (
      SELECT 1 FROM public.zane_social_blocks b
      WHERE (b.blocker_id = v_owner AND b.blocked_id = friends.friend_id)
         OR (b.blocker_id = friends.friend_id AND b.blocked_id = v_owner)
    )
  ORDER BY friends.friend_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.social_claim_notification_deliveries(
  p_event_key text,
  p_event_kind text,
  p_recipient_ids uuid[]
)
RETURNS TABLE(recipient_id uuid, claim_token timestamptz, state text)
LANGUAGE sql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH requested AS (
    SELECT DISTINCT id AS recipient_id
    FROM unnest(COALESCE(p_recipient_ids, ARRAY[]::uuid[])) AS ids(id)
    WHERE id IS NOT NULL
  ), stamp AS (
    SELECT clock_timestamp() AS claimed_at
  ), claimed AS (
    INSERT INTO public.zane_social_notification_deliveries AS delivery
      (event_key, recipient_id, event_kind, last_attempt_at)
    SELECT p_event_key, requested.recipient_id, p_event_kind, stamp.claimed_at
    FROM requested CROSS JOIN stamp
    WHERE NULLIF(trim(p_event_key), '') IS NOT NULL
    ON CONFLICT (event_key, recipient_id) DO UPDATE
      SET event_kind = EXCLUDED.event_kind,
          last_attempt_at = EXCLUDED.last_attempt_at
      WHERE delivery.delivered_at IS NULL
        AND (delivery.last_attempt_at IS NULL OR delivery.last_attempt_at < now() - interval '2 minutes')
    RETURNING delivery.recipient_id, delivery.last_attempt_at
  )
  SELECT requested.recipient_id,
         claimed.last_attempt_at AS claim_token,
         CASE
           WHEN claimed.recipient_id IS NOT NULL THEN 'claimed'
           WHEN delivery.delivered_at IS NOT NULL THEN 'delivered'
           ELSE 'busy'
         END AS state
  FROM requested
  LEFT JOIN claimed USING (recipient_id)
  LEFT JOIN public.zane_social_notification_deliveries delivery
    ON delivery.event_key = p_event_key AND delivery.recipient_id = requested.recipient_id
  ORDER BY requested.recipient_id;
$function$;

CREATE OR REPLACE FUNCTION public.social_finish_notification_deliveries(
  p_event_key text,
  p_results jsonb
)
RETURNS integer
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result jsonb;
  v_changed integer;
  v_total integer := 0;
BEGIN
  IF jsonb_typeof(COALESCE(p_results, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'p_results must be an array';
  END IF;
  FOR v_result IN SELECT value FROM jsonb_array_elements(COALESCE(p_results, '[]'::jsonb))
  LOOP
    UPDATE public.zane_social_notification_deliveries
    SET delivered_at = CASE WHEN COALESCE((v_result->>'delivered')::boolean, false) THEN now() ELSE delivered_at END,
        last_attempt_at = CASE WHEN COALESCE((v_result->>'delivered')::boolean, false) THEN last_attempt_at ELSE NULL END
    WHERE event_key = p_event_key
      AND recipient_id = (v_result->>'recipient_id')::uuid
      AND delivered_at IS NULL
      AND last_attempt_at = (v_result->>'claim_token')::timestamptz;
    GET DIAGNOSTICS v_changed = ROW_COUNT;
    v_total := v_total + v_changed;
  END LOOP;
  RETURN v_total;
END;
$function$;

